function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 - 20 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 - 20 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 70 - 30 * Math.cos(t), H/2 - 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70 - 30 * Math.cos(t), H/2 - 20 * Math.sin(t) + 10);
  ctx.lineTo(W/2 - 70 - 30 * Math.cos(t), H/2 - 20 * Math.sin(t) - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70 - 30 * Math.cos(t) - 10, H/2 - 20 * Math.sin(t));
  ctx.lineTo(W/2 - 70 - 30 * Math.cos(t) + 10, H/2 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Suffering', W/2, H/2 + 80 + 10 * Math.sin(t));
  ctx.restore();
}
